import assert from 'node:assert/strict';
const loader=await import('./anatomy-loader.mjs').catch(()=>null);
assert.equal(typeof loader?.loadAnatomyStream,'function','Anatomy must stream real points before both files finish');
const xyz=new Float32Array([.2,.3,.4,-.1,.5,.6,.7,.8,.9,-.2,-.3,-.4]);
const normals=new Float32Array([0,0,1,1,0,0,0,1,0,0,0,-1]);
const bytes=a=>new Uint8Array(a.buffer);
const response=(data,cuts=[13,14,21,data.length])=>new Response(new ReadableStream({start(c){let offset=0;for(const end of cuts){c.enqueue(data.slice(offset,end));offset=end;}c.close();}}));
let release;const gate=new Promise(resolve=>release=resolve),events=[];let settled=false;
const fetchSlow=async path=>path.includes('.normals.')?response(bytes(normals)):new Response(new ReadableStream({async start(c){c.enqueue(bytes(xyz).slice(0,13));await gate;c.enqueue(bytes(xyz).slice(13,21));c.enqueue(bytes(xyz).slice(21));c.close();}}));
const pending=loader.loadAnatomyStream({pointCount:4,fetchImpl:fetchSlow,onProgress:event=>events.push({...event})}).then(result=>{settled=true;return result;});
while(!events.some(x=>x.positionPoints===1))await new Promise(resolve=>setImmediate(resolve));
assert.equal(settled,false,'First complete XYZ point must be visible while the response is still pending');
assert.ok(events.some(x=>x.positionPoints===1&&x.receivedBytes<96));
release();const result=await pending;
assert.deepEqual(result.positions,xyz);assert.deepEqual(result.normals,normals);
assert.equal(events.at(-1).receivedBytes,96);assert.equal(events.at(-1).positionPoints,4);assert.equal(events.at(-1).normalPoints,4);
for(let i=1;i<events.length;i++)assert.ok(events[i].receivedBytes>=events[i-1].receivedBytes,'Progress must not move backwards');
const fetchData=(positions=bytes(xyz),surface=bytes(normals))=>async path=>response(path.includes('.normals.')?surface:positions,[13,(path.includes('.normals.')?surface:positions).length]);
await assert.rejects(loader.loadAnatomyStream({pointCount:4,fetchImpl:fetchData(bytes(xyz).slice(0,47))}),/exactly|length|truncated/i);
await assert.rejects(loader.loadAnatomyStream({pointCount:4,fetchImpl:fetchData(new Uint8Array(49))}),/exactly|length|large/i);
const nan=new Float32Array(xyz);nan[2]=NaN;
await assert.rejects(loader.loadAnatomyStream({pointCount:4,fetchImpl:fetchData(bytes(nan))}),/finite/i);
await assert.rejects(loader.loadAnatomyStream({pointCount:4,fetchImpl:fetchData(bytes(xyz),new Uint8Array(48))}),/normal/i);
await assert.rejects(loader.loadAnatomyStream({pointCount:4,fetchImpl:async()=>new Response('',{status:404})}),/404/);
const fallback=await loader.loadAnatomyStream({pointCount:4,fetchImpl:async path=>({ok:true,body:null,arrayBuffer:async()=>bytes(path.includes('.normals.')?normals:xyz).buffer})});
assert.deepEqual(fallback.positions,xyz);assert.deepEqual(fallback.normals,normals);
// Exercise the early preview lifecycle without a browser, with actual anatomy
// bytes and a held response. Rendering assertions concern draw calls, not a
// claim of browser visual acceptance.
const {readFile}=await import('node:fs/promises');
const actualXYZ=new Uint8Array(await readFile(new URL('./assets/anatomy/brain-65536.xyz.f32',import.meta.url)));
const actualNormals=new Uint8Array(await readFile(new URL('./assets/anatomy/brain-65536.normals.f32',import.meta.url)));
const elements=new Map();const plotted=[];let pendingFrame=null,disconnected=false;
for(const id of ['brain-loading','brain-preview','brain','anatomy-loading-label','anatomy-loading-detail'])elements.set(id,{hidden:false,attributes:{},setAttribute(k,v){this.attributes[k]=v;},removeAttribute(k){delete this.attributes[k];},textContent:''});
const preview=elements.get('brain-preview');preview.getBoundingClientRect=()=>({width:800,height:700});preview.getContext=()=>({fillRect(...args){assert.ok(args.every(Number.isFinite));plotted.push(args);}});
globalThis.document={hidden:false,getElementById:id=>elements.get(id),addEventListener(){},removeEventListener(){}};
globalThis.window={devicePixelRatio:1};
globalThis.ResizeObserver=class{observe(){}disconnect(){disconnected=true;}};
globalThis.requestAnimationFrame=fn=>{pendingFrame=fn;return 1;};globalThis.cancelAnimationFrame=()=>pendingFrame=null;
let resumePreview;const previewGate=new Promise(resolve=>resumePreview=resolve);
globalThis.fetch=async path=>new Response(new ReadableStream({async start(c){const data=path.includes('.normals.')?actualNormals:actualXYZ;c.enqueue(data.slice(0,262144));await previewGate;c.enqueue(data.slice(262144));c.close();}}));
const ui=await import('./anatomy-loader.mjs?preview-lifecycle-test');
while(window.cortexAnatomyLoading.receivedBytes<524288)await new Promise(resolve=>setImmediate(resolve));
pendingFrame();assert.ok(plotted.length>0&&plotted.length<16384,'A partial anatomical brain must be drawn before download completes');
assert.equal(elements.get('brain-loading').attributes['aria-valuenow'],'33');
assert.equal(window.cortexAnatomyLoading.positionPoints,21845);
assert.equal(elements.get('brain-loading').hidden,false);
resumePreview();await ui.anatomyReady;pendingFrame();
assert.equal(plotted.length,16384);assert.equal(window.cortexAnatomyLoading.positionPoints,65536);
assert.equal(elements.get('brain-loading').hidden,false,'Do not hide preview until the WebGL renderer confirms its first frame');
ui.completeAnatomyLoading();assert.equal(elements.get('brain-loading').hidden,true);assert.equal(window.cortexAnatomyLoading.stage,'ready');assert.equal(disconnected,true);
let releaseHeaders;const headersGate=new Promise(resolve=>releaseHeaders=resolve);
globalThis.fetch=async path=>{await headersGate;return new Response(path.includes('.normals.')?actualNormals:actualXYZ);};
const failedUi=await import('./anatomy-loader.mjs?renderer-failure-test');
failedUi.failAnatomyLoading(new Error('WebGL unavailable'));releaseHeaders();await failedUi.anatomyReady;
assert.equal(window.cortexAnatomyLoading.stage,'error','Late network completion must not erase renderer failure');
assert.equal(elements.get('anatomy-loading-label').textContent,'MODEL LOAD FAILED');
assert.equal(elements.get('brain').attributes['aria-busy'],'false');assert.equal(pendingFrame,null);
failedUi.completeAnatomyLoading();assert.equal(elements.get('brain-loading').hidden,false,'A failed renderer must not dismiss the error');
console.log(JSON.stringify({ok:true,progressBeforeDownloadCompletion:true,arbitraryByteBoundaries:true,exactArrays:true,invalidAssetsRejected:true,arrayBufferFallback:true,partialPreviewDraws:true,progressMatchesBytes:true,handoffWaitsForFirstWebGLFrame:true,rendererFailureStaysVisible:true}));
